 async function loadLive(c:SupabaseClient,token:string){try{const [{data:a,error:ae},{data:p,error:pe},{data:j}]=await Promise.all([c.from('omnipost_social_accounts').select('*').order('created_at',{ascending:false}),c.from('omnipost_posts').select('*').order('created_at',{ascending:false}),c.from('omnipost_publish_jobs').select('*')]);if(ae||pe)throw ae||pe;setAccounts((a||[]).map((v:any)=>({...v,handle:v.handle||''})));setPosts((p||[]).map((v:any)=>({...v.data,id:v.id,status:v.status,scheduledAt:v.scheduled_at||v.data.scheduledAt||'',createdAt:v.created_at,updatedAt:v.updated_at})));setJobs(j||[]);const uid=session?.user?.id;if(uid){const {data:files}=await c.storage.from('omnipost-media').list(uid,{limit:100});if(files){setAssets(files.filter((f:any)=>f.name&&!f.name.startsWith('.')).map((f:any)=>({name:f.name,url:c.storage.from('omnipost-media').getPublicUrl(uid+'/'+f.name).data.publicUrl,type:/\.(mp4|mov)$/i.test(f.name)?'video' as const:'image' as const})));}}}catch(e){flash('Could not load workspace: '+String(e),'bad');}}
 async function authApi(path:string,method='POST',body?:any){if(!session)throw Error('Sign in first');const r=await fetch(path,{method,headers:{Authorization:`Bearer ${session.access_token}`,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');return j;}
