 async function signIn(e:any){e.preventDefault();if(!client||loading)return;setNotice(null);setLoading(true);try{
  if(authMode==='password'){
    const {error}=await client.auth.signInWithPassword({email:email.trim(),password});
    if(error)throw error;
    setPassword('');setLoginSent(false);
  }else{
    const last=Number(localStorage.getItem('omnipost-otp-last-request')||'0');
    if(Date.now()-last<60000)throw Error('A sign-in link was requested recently. Check your inbox and avoid requesting another link for at least 60 seconds.');
    const {error}=await client.auth.signInWithOtp({email:email.trim(),options:{emailRedirectTo:location.origin}});
    if(error)throw error;
    localStorage.setItem('omnipost-otp-last-request',String(Date.now()));
    setLoginSent(true);
  }
 }catch(err:any){
  if(err?.status===429||err?.code==='over_email_send_rate_limit'||/email rate limit exceeded/i.test(String(err?.message||err))){
   flash('Supabase has reached its shared email-sending limit. Do not keep retrying. Try a link already in your inbox, use password sign-in if you previously set a password, or try again after the email quota resets.','bad');
  }else if(authMode==='password'&&/invalid login credentials/i.test(String(err?.message||err))){
   flash('Email or password was incorrect, or this account has no password yet. Use an email link once the sending quota resets to set a password.','bad');
  }else flash(err instanceof Error?err.message:String(err),'bad');
 }finally{setLoading(false)}}
 async function saveAIKey(e:any){e.preventDefault();if(!session||aiSetupBusy)return;setAiSetupBusy(true);try{const result=await authApi('/api/ai/settings','POST',{key:aiKeyInput.trim(),model:'gemini-2.5-flash'});setAiReady(!!result.configured);setAiStatusChecked(true);setAiKeyInput('');flash('Gemini is connected securely. Open Omni AI to generate a real response.','ok');setAssistantOpen(true);}catch(e){flash('Gemini connection: '+String(e),'bad')}finally{setAiSetupBusy(false)}}
