 async function generateAI(){if(!aiTopic.trim()){flash('Add your topic or campaign brief first.','bad');return;}if(!aiReady){flash('Connect your free Gemini API key in Settings → AI connection to generate real content.','bad');setView('settings');return;}setBusyAI(true);try{const result:any=await authApi('/api/ai','POST',{topic:aiTopic,tone:aiTone,goal:aiGoal,audience:aiAudience,platforms:draft.platforms.length?draft.platforms:PLATFORMS,brand});setDraft(d=>({...d,title:result.title||d.title,caption:result.caption||d.caption,tags:result.tags||d.tags,cta:result.cta||d.cta,firstComment:result.firstComment||d.firstComment,altText:result.altText||d.altText,overrides:{...d.overrides,...result.overrides},aiGenerated:true}));setView('compose');flash('AI content generated. Review accuracy before publishing.','ok');}catch(e){flash('AI generation failed: '+String(e),'bad')}finally{setBusyAI(false)}}

 function applyAssistantDraft(suggestion:Partial<ContentPost>){setDraft(d=>({...d,title:suggestion.title||'',caption:suggestion.caption||'',tags:suggestion.tags||'',cta:suggestion.cta||'',firstComment:suggestion.firstComment||'',altText:suggestion.altText||'',overrides:{...d.overrides,...(suggestion.overrides||{})},platforms:suggestion.platforms?.length?suggestion.platforms:d.platforms,scheduledAt:suggestion.scheduledAt?inputDatetime(new Date(suggestion.scheduledAt)):d.scheduledAt,aiGenerated:true}));setView('compose');flash('AI content placed in the editor. Review and choose your accounts before saving.','ok');}
