 const weekdays=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];const first=new Date(calendarDate.getFullYear(),calendarDate.getMonth(),1),daysInMonth=new Date(calendarDate.getFullYear(),calendarDate.getMonth()+1,0).getDate(),offset=first.getDay();
 const titleFor:Record<View,string>={overview:'Workspace overview',compose:'Create a post',calendar:'Content calendar',posts:'Content library',library:'Media library',ai:'AI content studio',accounts:'Connected accounts',analytics:'Content analytics',settings:'Workspace settings'};
